DECODER = {1: 18446744073709551616, 2: 36893488147419103232, 9: 8912896, 11: 9223372036854775808, 22: 16, 34: 4503633987108864, 40: 281543696187392, 43: 8388616, 46: 262208, 51: 4406636445696, 57: 262145, 58: 524289, 63: 824633720832, 65: 4503599629467648, 75: 8589934848, 77: 2251799813947392, 80: 17592188141568, 83: 134217792, 85: 2251799813701632, 89: 35184372350976, 96: 1770887431076116955136, 124: 9007199254740992, 129: 147862182965828124672, 132: 4647714815446351872, 140: 1152921504606846976, 141: 19599665578316398592, 142: 4899916394579099648, 147: 576460752303423520, 150: 2361183241434822606864, 154: 2361183241434822606912, 157: 1180735735974206636032, 159: 297453748188566519808, 163: 72057594037929984, 168: 38046409652025952256, 171: 90071994694893568, 178: 576460752304472064, 179: 2361184367334763003904, 180: 576460752311812096, 182: 2323857407790284800, 183: 72057594038059008, 186: 2305878227945521152, 187: 144115188080050176, 195: 144115188109410304, 199: 36028865738440960, 204: 2305843009230471168, 208: 144115188344291456, 212: 72057596185411584, 215: 144115190223339520, 224: 4132070672510939561984, 225: 36029896530591744, 229: 295185059876278632448, 232: 36046389205008384, 233: 72057594306365440, 240: 580964351930793984, 249: 40532396646334464, 255: 1153202979583557632}

def syndrome(word: int) -> int:
    value = 0
    for position, column in enumerate(H_COLUMNS):
        if (word >> position) & 1:
            value ^= column
    return value

def encode(data: int) -> int:
    if data < 0 or data >= (1 << K):
        raise ValueError("data does not fit")
    out = 0
    for bit in range(N):
        value = 0
        for source in range(K):
            value ^= ((data >> source) & 1) & G[source][bit]
        out |= value << bit
    return out

def decode(received: int, original_data: int | None = None) -> dict:
    syn = syndrome(received)
    if syn == 0:
        decoded = received & ((1 << K) - 1)
        outcome = "correct" if original_data is None or decoded == original_data else "silent_corruption"
        return {"outcome": outcome, "syndrome": syn, "decoded_data": decoded, "correction_mask": 0}
    if syn not in DECODER:
        return {"outcome": "detected_uncorrectable", "syndrome": syn, "decoded_data": None, "correction_mask": 0}
    mask = DECODER[syn]
    corrected = received ^ mask
    if syndrome(corrected) != 0:
        return {"outcome": "decoder_failure", "syndrome": syn, "decoded_data": None, "correction_mask": mask}
    decoded = corrected & ((1 << K) - 1)
    outcome = "corrected" if original_data is None or decoded == original_data else "silent_corruption"
    return {"outcome": outcome, "syndrome": syn, "decoded_data": decoded, "correction_mask": mask}

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("data", type=lambda value: int(value, 0))
    parser.add_argument("error_mask", type=lambda value: int(value, 0))
    args = parser.parse_args()
    codeword = encode(args.data)
    result = decode(codeword ^ args.error_mask, args.data)
    print(f"{codeword} {codeword ^ args.error_mask} {result['syndrome']} {result['outcome']} {result['decoded_data'] if result['decoded_data'] is not None else -1}")

if __name__ == "__main__":
    main()
